import{_ as t,o as a,c as i,a4 as r}from"./chunks/framework.CzJ_HCFe.js";const u=JSON.parse('{"title":"Raman work and inspected-artifact identity audit","description":"","frontmatter":{},"headers":[],"relativePath":"research/election-chart-automation/raman-artifact-identity-audit/report.md","filePath":"research/election-chart-automation/raman-artifact-identity-audit/report.md","lastUpdated":1788614098000}'),n={name:"research/election-chart-automation/raman-artifact-identity-audit/report.md"};function o(d,e,l,s,c,p){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="raman-work-and-inspected-artifact-identity-audit" tabindex="-1">Raman work and inspected-artifact identity audit <a class="header-anchor" href="#raman-work-and-inspected-artifact-identity-audit" aria-label="Permalink to &quot;Raman work and inspected-artifact identity audit&quot;">​</a></h1><p>Story: <a href="https://github.com/socraticsurge/telugu-calendar-utilities/issues/366" target="_blank" rel="noreferrer">#366</a></p><p>Parent event: <a href="https://github.com/socraticsurge/telugu-calendar-utilities/issues/265" target="_blank" rel="noreferrer">#265</a></p><p>Audience: maintainers, computation reviewers, and readers checking Muhurtam sources</p><p>Revalidated: 2026-09-04</p><h2 id="direct-answer" tabindex="-1">Direct answer <a class="header-anchor" href="#direct-answer" aria-label="Permalink to &quot;Direct answer&quot;">​</a></h2><p>The repository had represented one catalogue record and one hosted PDF as though they were the same edition. They are not the same inspected object. This release candidate separates them in canonical provenance:</p><ol><li>BVR-MUHURTHA-1993 is the bibliographic record for B. V. Raman, <em>Muhurtha (Electional Astrology)</em>, UBS Publishers&#39; Distributors, 1993, ISBN 9788185674681, 181 catalogued pages.</li><li>BVR-MUHURTHA-CHISTABO-2020 is the artifact actually inspected: a 78-physical-page PDF whose own notice identifies it as a 2020 Simon/Chistabo re-edit with bracketed additions, typo corrections, and the appendix omitted.</li></ol><p>No scan of the 181-page 1993 edition was inspected. The Chistabo notice says its text was checked against an unspecified original scanned PDF; it does not identify that input as the 1993 UBS edition. The canonical record therefore links the objects while explicitly leaving an exact edition match unverified.</p><h2 id="scope-and-method" tabindex="-1">Scope and method <a class="header-anchor" href="#scope-and-method" aria-label="Permalink to &quot;Scope and method&quot;">​</a></h2><p>The audit covers every provenance claim linked to BVR-MUHURTHA-1993 at the release base, plus human-readable pages and generated source disclosures that project those claims. It does not reassess the meaning, admission set, score, or ranking effect of any rule.</p><p>The hosted artifact was downloaded again on 2026-09-04. Its checksum, byte size, page count, metadata, editorial notice, internal folios, chapter transitions, and each claimed passage were checked directly. Google Books and Open Library were independently read for the 1993 catalogue identity.</p><h2 id="inspected-artifact" tabindex="-1">Inspected artifact <a class="header-anchor" href="#inspected-artifact" aria-label="Permalink to &quot;Inspected artifact&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Verified value</th></tr></thead><tbody><tr><td>URL</td><td><a href="https://www.panchanga.lv/wp-content/uploads/2020/06/Muhurta_Raman.pdf" target="_blank" rel="noreferrer">https://www.panchanga.lv/wp-content/uploads/2020/06/Muhurta_Raman.pdf</a></td></tr><tr><td>Accessed</td><td>2026-09-04</td></tr><tr><td>SHA-256</td><td>b8b878a444a487c83810329fdf8f057c40e92221a867db480d864da8be21a133</td></tr><tr><td>Bytes</td><td>2,172,882</td></tr><tr><td>Physical PDF pages</td><td>78</td></tr><tr><td>PDF title</td><td>Muhurta-Raman Eng</td></tr><tr><td>PDF creation/modification metadata</td><td>2020-06-17 16:29:55 IST</td></tr><tr><td>Producer</td><td>Mac OS X 10.13.6 Quartz PDFContext</td></tr><tr><td>Editorial disclosure</td><td>physical PDF p. 3 / internal folio II</td></tr></tbody></table><p>The title page says that the document is “as per” B. V. Raman. Physical PDF p. 3 identifies Simon, also called Chistabo, as editor and describes re-editing, corrections, bracketed additions, and appendix omission. These visible statements rule out treating the file as an inspected copy of the catalogued 1993 edition.</p><h2 id="page-number-model" tabindex="-1">Page-number model <a class="header-anchor" href="#page-number-model" aria-label="Permalink to &quot;Page-number model&quot;">​</a></h2><p>The derivative has two offsets:</p><ul><li>physical PDF pp. 1–3 are derivative front matter;</li><li>physical PDF pp. 4–36 map to internal printed pp. 1–33 (internal = physical - 3);</li><li>physical PDF p. 37 is an unnumbered continuation/table page;</li><li>physical PDF pp. 38–78 map to internal printed pp. 34–74 (internal = physical - 4).</li></ul><p>A global “printed page + 4” rewrite is therefore unsafe. All canonical Raman locators now say both <strong>internal printed page</strong> and <strong>physical PDF page</strong> and name the Chistabo derivative.</p><h2 id="claim-gap-matrix" tabindex="-1">Claim-gap matrix <a class="header-anchor" href="#claim-gap-matrix" aria-label="Permalink to &quot;Claim-gap matrix&quot;">​</a></h2><p>All 34 active provenance claims associated with the bibliographic work were reconciled. The machine-readable fixture records the pre-migration locator, the directly checked locator, canonical source identifiers, and status for each claim.</p><table tabindex="0"><thead><tr><th>Audit state</th><th style="text-align:right;">Count</th><th>Release treatment</th></tr></thead><tbody><tr><td>aligned</td><td style="text-align:right;">13</td><td>Coordinates retained; artifact and page vocabulary made explicit</td></tr><tr><td>correction_required</td><td style="text-align:right;">17</td><td>Coordinates or range corrected from direct artifact inspection</td></tr><tr><td>no_locator</td><td style="text-align:right;">4</td><td>Kept work-only and needs_locator; no derivative inspection implied</td></tr></tbody></table><p>High-impact corrections include:</p><ul><li>Vehicle: internal printed p. 11 / physical PDF p. 14, not internal p. 10.</li><li>Well digging: internal printed p. 52 / physical PDF p. 56, not p. 51 / p. 55.</li><li>Roof laying: internal printed p. 51 / physical PDF p. 55, not p. 50 / p. 54.</li><li>Naming: internal printed p. 22 / physical PDF p. 25, not internal p. 21.</li><li>Completed-house and building-land purchase: internal printed p. 54 / physical PDF p. 58, not p. 53 / p. 57.</li><li>Home repair: internal printed pp. 54–55 / physical PDF pp. 58–59; the former range began early and omitted the continuation.</li><li>General Panchanga Suddhi: internal printed p. 12 / physical PDF p. 15, not “printed p. 11.”</li><li>Vidyarambha: internal printed p. 23 / physical PDF p. 26, not physical p. 27.</li><li>Karnavedha: physical PDF p. 26 visibly carries internal footer 23; the earlier internal-p.22 note was wrong.</li><li>Tyajyakala: internal printed p. 7 / physical PDF p. 10.</li><li>Panchak: internal printed pp. 8–9 / physical PDF pp. 11–12.</li></ul><p>The complete 34-row ledger is in tests/fixtures/raman-artifact-identity-audit-v1.json.</p><h2 id="authority-and-implementation-boundary" tabindex="-1">Authority and implementation boundary <a class="header-anchor" href="#authority-and-implementation-boundary" aria-label="Permalink to &quot;Authority and implementation boundary&quot;">​</a></h2><p>The artifact verifies what the derivative says and where it says it. It does not establish that every editorial choice reproduces the 1993 edition, promote the derivative to primary scripture, or make the cited lineage universal.</p><p>Located Raman claims now cite both the bibliographic work and the exact artifact inspected. The four claims without a locator remain linked only to the bibliographic work and retain needs_locator; this avoids converting a source association into false inspection evidence.</p><p>Non-source rule semantics remain unchanged after source metadata is stripped, and the four protected scoring implementations remain byte-identical. The source split changes provenance records, source disclosures, corrected page coordinates, release metadata, and tests only. Runtime predicates, accepted event values, ranking weights, the frozen engines, ICS generation, and workflows are unchanged.</p><h2 id="source-ledger" tabindex="-1">Source ledger <a class="header-anchor" href="#source-ledger" aria-label="Permalink to &quot;Source ledger&quot;">​</a></h2><ul><li>B. V. Raman, <em>Muhurtha (Electional Astrology)</em>, UBS Publishers&#39; Distributors, 1993, ISBN 9788185674681, 181 pages: <a href="https://books.google.com/books/about/Muhurtha_Electional_Astrology.html?id=nHQlAcBkDXIC" target="_blank" rel="noreferrer">Google Books catalogue</a> and <a href="https://openlibrary.org/books/OL9860226M/Muhurtha_%28Electional_Astrology%29" target="_blank" rel="noreferrer">Open Library edition record</a>. These corroborate bibliographic identity; neither was used as full-text evidence.</li><li>B. V. Raman / Simon (Chistabo), <em>Muhurtha (Electional Astrology)</em>, 2020 re-edited PDF: <a href="https://www.panchanga.lv/wp-content/uploads/2020/06/Muhurta_Raman.pdf" target="_blank" rel="noreferrer">inspected artifact</a>. This supplies the visible editorial notice and every physical/internal page coordinate in the migrated claims.</li></ul><h2 id="stop-condition-and-remaining-gap" tabindex="-1">Stop condition and remaining gap <a class="header-anchor" href="#stop-condition-and-remaining-gap" aria-label="Permalink to &quot;Stop condition and remaining gap&quot;">​</a></h2><p>The research stopped after the hosted file&#39;s identity and all 34 active claim states were reproducible, the 17 corrections had direct page evidence, and a second catalogue independently corroborated the 1993 record. Another search would not change the required split.</p><p>One material gap remains: no physical or digitized copy of the catalogued 181-page 1993 UBS edition has been inspected. A future edition-collation story may compare its text with the Chistabo derivative, but that work is not needed to state the present evidence truthfully.</p>',34)])])}const m=t(n,[["render",o]]);export{u as __pageData,m as default};
